class ScannedPayment {
  final String address;

  /// 0 when the request leaves the amount to the payer.
  final BigInt amountZat;

  /// Text memo (empty if none or not text).
  final String memo;

  /// What the link calls the recipient (ZIP 321 `label`; empty if none). Written by
  /// whoever made the link: show it as the link's claim, never as verified.
  final String label;

  /// The link's note to the payer (ZIP 321 `message`; empty if none). Same caveat.
  final String message;

  const ScannedPayment({
    required this.address,
    required this.amountZat,
    required this.memo,
    required this.label,
    required this.message,
  });

  @override
  int get hashCode =>
      address.hashCode ^
      amountZat.hashCode ^
      memo.hashCode ^
      label.hashCode ^
      message.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ScannedPayment &&
          runtimeType == other.runtimeType &&
          address == other.address &&
          amountZat == other.amountZat &&
          memo == other.memo &&
          label == other.label &&
          message == other.message;
}

class ScannedRequest {
  /// Empty when `problem` is set.
  final List<ScannedPayment> payments;

  /// Why it can't be paid from this vault (empty when fine).
  final String problem;

  const ScannedRequest({required this.payments, required this.problem});

  @override
  int get hashCode => payments.hashCode ^ problem.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ScannedRequest &&
          runtimeType == other.runtimeType &&
          payments == other.payments &&
          problem == other.problem;
}

/// A signer moving to a new phone, waiting for approvals.
class SeatMove {
  /// The signer who lost their phone (hex key).
  final String oldKeyHex;

  /// The new phone's key (hex).
  final String newKeyHex;

  /// Members who approved so far (hex keys).
  final List<String> approvals;
  final int needed;

  /// The recovery code, rebuilt from the log, for approving from this list.
  final String code;

  const SeatMove({
    required this.oldKeyHex,
    required this.newKeyHex,
    required this.approvals,
    required this.needed,
    required this.code,
  });

  @override
  int get hashCode =>
      oldKeyHex.hashCode ^
      newKeyHex.hashCode ^
      approvals.hashCode ^
      needed.hashCode ^
      code.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SeatMove &&
          runtimeType == other.runtimeType &&
          oldKeyHex == other.oldKeyHex &&
          newKeyHex == other.newKeyHex &&
          approvals == other.approvals &&
          needed == other.needed &&
          code == other.code;
}

class SendProgress {
  final SendStage stage;
  final int received;
  final int needed;
  final String? txid;
  final ZafeError? error;

  const SendProgress({
    required this.stage,
    required this.received,
    required this.needed,
    this.txid,
    this.error,
  });

  @override
  int get hashCode =>
      stage.hashCode ^
      received.hashCode ^
      needed.hashCode ^
      txid.hashCode ^
      error.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SendProgress &&
          runtimeType == other.runtimeType &&
          stage == other.stage &&
          received == other.received &&
          needed == other.needed &&
          txid == other.txid &&
          error == other.error;
}

enum SendStage {
  /// Signing requests are out; the transaction proof is being built meanwhile.
  collecting,
  sent,

  /// Not sent; `error` says why. Retrying resumes the same signing round.
  failed,
}
